use vstd::prelude::*;

verus! {

    // Given a slice `a` of mathematical integers, find an index `i` such that
    // a[i], a[i+1], a[i+2] are all equal, if any such triple exists.
    // Otherwise return `a.len()`.
    //
    // Post‐conditions:
    //  1. `index <= a.len()`
    //  2. If `index == a.len()`, then no triple of equal consecutive elements occurs.
    //  3. If `index < a.len()`, then `index + 2 < a.len()` and
    //     `a[index] == a[index+1] == a[index+2]`.
    fn get_triple(a: &[int]) -> (index: usize)
        ensures
            index <= a.len(),
            if index == a.len() {
                // No triple exists anywhere in `a`.
                forall |j: usize| j + 2 < a.len() ==> !(a[j] == a[j+1] && a[j+1] == a[j+2])
            } else {
                // We found a triple at position `index`.
                index + 2 < a.len() &&
                a[index] == a[index+1] &&
                a[index+1] == a[index+2]
            }
    {
        let mut i: usize = 0;
        while i + 2 < a.len()
            invariant
                // We never advance past `a.len()`.
                i <= a.len(),
                // Up to (but not including) `i`, there is no triple.
                forall |j: usize| j < i && j + 2 < a.len() ==>
                    !(a[j] == a[j+1] && a[j+1] == a[j+2])
            decreases a.len() - i
        {
            if a[i] == a[i+1] && a[i+1] == a[i+2] {
                return i;
            }
            i = i + 1;
        }
        // No triple found.
        a.len()
    }

}

